use std::{fs,path::Path,collections::{BTreeMap,BTreeSet},process::Command};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-poseidon-across8";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn median(mut v:Vec<f64>)->f64{v.sort_by(f64::total_cmp);assert!(!v.is_empty());if v.len()%2==1{v[v.len()/2]}else{(v[v.len()/2-1]+v[v.len()/2])/2.}}
fn gm(v:&[f64])->f64{(v.iter().map(|x|x.ln()).sum::<f64>()/v.len()as f64).exp()}
fn main(){let r=Path::new(R);assert_eq!(read(r.join("measure/result.json"))["status"],"complete");let pins=read(r.join("measurement-pins.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}
 let mut rows=Vec::new();for job in read(r.join("jobs.json")).as_array().unwrap(){let log=fs::read_to_string(r.join("measure").join(job["name"].as_str().unwrap()).join("stdout.log")).unwrap();let s:Value=serde_json::from_str(log.lines().find_map(|l|l.strip_prefix("SUMMARY ")).unwrap()).unwrap();assert_eq!(s["all_outputs_match_interpreter"],true);assert_eq!(s["timed_allocation_calls"],0);assert_eq!(s["mode"],job["mode"]);let expected=if job["phase"]=="profile"{job["iterations"].clone()}else{job["case"]["iterations"].clone()};assert_eq!(s["iterations"],expected);rows.push(json!({"job":job,"result":s}));}assert_eq!(rows.len(),339);
 let mut cases=BTreeMap::new();let mut calibration=Vec::new();let mut failures=Vec::new();let mut aggregates:BTreeMap<&str,Vec<Vec<f64>>>=[("control-a",vec![vec![];7]),("control-b",vec![vec![];7])].into_iter().collect();
 for case in read(r.join("cases.json")).as_array().unwrap(){let name=case["name"].as_str().unwrap();let values=|mode:&str|->Vec<f64>{(0..7).map(|block|rows.iter().find(|x|x["job"]["phase"]=="latency"&&x["job"]["block"]==block&&x["job"]["case"]["name"]==name&&x["job"]["mode"]==mode).unwrap()["result"]["ns_per_hash"].as_f64().unwrap()).collect()};let a=values("control-a");let b=values("control-b");let v=values("batch");let cal:Vec<_>=a.iter().zip(&b).map(|(a,b)|b/a).collect();for(block,x)in cal.iter().enumerate(){if !(1./1.05..=1.05).contains(x){calibration.push(format!("{name} b{block} B/A={x}"));}}let med=median(cal.clone());if !(1./1.03..=1.03).contains(&med){calibration.push(format!("{name} median B/A={med}"));}
  let mut pairs=BTreeMap::new();for(control,base)in [("control-a",&a),("control-b",&b)]{let ratios:Vec<_>=v.iter().zip(base).map(|(v,b)|v/b).collect();for(block,x)in ratios.iter().enumerate(){aggregates.get_mut(control).unwrap()[block].push(*x);}let geo=gm(&ratios);if geo>1.02{failures.push(format!("{name} batch/{control}={geo}"));}pairs.insert(control,json!({"geometric_ratio":geo,"wins":ratios.iter().filter(|x|**x<1.).count(),"ratios":ratios}));}cases.insert(name.to_string(),json!({"case":case,"control_a_ns_per_hash":median(a),"control_b_ns_per_hash":median(b),"batch_ns_per_hash":median(v),"calibration_ratios":cal,"pairs":pairs}));
 }let mut aggregate_stats=BTreeMap::new();for(control,blocks)in aggregates{let block_ratios:Vec<_>=blocks.iter().map(|v|{assert_eq!(v.len(),16);gm(v)}).collect();let ratio=gm(&block_ratios);let wins=block_ratios.iter().filter(|x|**x<1.).count();if ratio>=1.||wins<4{failures.push(format!("aggregate batch/{control}={ratio},wins{wins}"));}aggregate_stats.insert(control,json!({"geometric_ratio":ratio,"wins":wins,"block_ratios":block_ratios}));}
 let mut profiles=BTreeMap::new();let mut raw=BTreeMap::new();for mode in ["control-a","control-b","batch"]{let text=fs::read_to_string(r.join(format!("measure/samples-{mode}/stdout.log"))).unwrap();assert!(!text.contains("PERF_RECORD_LOST")&&!text.lines().any(|l|l.split_whitespace().any(|w|w=="LOST")));let mut pids=BTreeSet::new();let mut tids=BTreeSet::new();let mut symbols:BTreeMap<String,(usize,u64)>=BTreeMap::new();let mut period=0u64;let mut samples=0;
  for line in text.lines(){let f:Vec<_>=line.split_whitespace().collect();if f.len()<7||f[4]!="cycles:u:"{continue;}let(pid,tid)=f[1].split_once('/').unwrap();pids.insert(pid.to_string());tids.insert(tid.to_string());let n:f64=f[3].parse().unwrap();assert!(n>=1.&&n.fract()==0.);let n=n as u64;period=period.checked_add(n).unwrap();samples+=1;let e=symbols.entry(f[6].into()).or_default();e.0+=1;e.1+=n;
  }assert!(samples>0);assert_eq!(pids.len(),1);assert_eq!(tids.len(),1);let mut list:Vec<_>=symbols.into_iter().map(|(sym,(count,p))|json!({"symbol":sym,"samples":count,"period":p,"percent":100.*p as f64/period as f64})).collect();list.sort_by(|a,b|b["period"].as_u64().cmp(&a["period"].as_u64()));profiles.insert(mode,json!({"samples":samples,"period":period,"pids":pids,"tids":tids,"lost_records":0,"symbols":list}));
  let data=r.join(format!("profiles/{mode}/perf.data"));let out=Command::new("sudo").args(["-n","sha256sum"]).arg(&data).output().unwrap();assert!(out.status.success());let h=String::from_utf8(out.stdout).unwrap().split_whitespace().next().unwrap().to_string();raw.insert(data.display().to_string(),h);
 }
 let a=json!({"cases":cases,"aggregates":aggregate_stats,"calibration_failures":calibration,"speed_or_nonregression_failures":failures,"component_advances":calibration.is_empty()&&failures.is_empty(),"profiles":profiles,"all339_outputs_match_interpreter":true,"all339_timed_allocations_zero":true,"SDK_requests":0,"Gnark_exports":0,"next_prior_count":6946,"adopted":false,"goal_achieved":false});save(r.join("rows.json"),&json!(rows));save(r.join("analysis.json"),&a);save(r.join("raw-local-only-sha256.json"),&json!(raw));println!("{}",serde_json::to_string_pretty(&json!({"advances":a["component_advances"],"aggregates":a["aggregates"],"calibration":a["calibration_failures"],"failures":a["speed_or_nonregression_failures"]})).unwrap());
}
